#!/usr/bin/env node
import { mkdirSync, writeFileSync, chmodSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const root = process.cwd();
const hookPath = resolve(root, '.git', 'hooks', 'pre-commit');
const hookDir = dirname(hookPath);

const script = `#!/usr/bin/env sh
# Auto-generated by scripts/install-git-hooks.mjs
npm run security:secret-scan:staged
`;

try {
  mkdirSync(hookDir, { recursive: true });
  writeFileSync(hookPath, script, 'utf8');
  try { chmodSync(hookPath, 0o755); } catch {}
  console.log('[hooks] Installed pre-commit secret scan hook.');
} catch (err) {
  console.warn('[hooks] Could not install pre-commit hook:', err?.message || err);
}
